param([ValidateSet('build','replay')][string]$Action='build',[ValidatePattern('^[a-z0-9-]+$')][string]$Name='early-amd-r1',[ValidateRange(0,8191)][int]$QueryStart=0,[ValidateRange(1,8192)][int]$QueryCount=64,[ValidateRange(1,32)][int]$Batch=8,[switch]$NativeProducts,[switch]$UseTable,[switch]$Baseline,[switch]$UseRcp,[ValidateRange(0,24)][int]$MemoryLayout=0)
$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-attention-parallel-probability-20260913'
$seed='D:\projects\AIMA-public-attention-compact-pv-20260913'
$sha='df1cd185dc503a6da850153a20c7612ba43a0bc9'
$bundle='D:\projects\attention-parallel-probability-df1cd18.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '0651a36afecd2b3fe92a7d285fb2147045c9677fa8f23e19f3ef17f587c3f792'){throw 'Bundle fingerprint mismatch'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD
 if($LASTEXITCODE -ne 0){throw 'Bundle fetch failed'}
 & git -C $seed worktree add --detach $repo $sha
 if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source checkout mismatch'}
$build=Join-Path $repo 'build\attention-replay'
$null=New-Item -ItemType Directory -Path $build -Force
$exe=Join-Path $build 'full-attention-capture-replay.exe'
$source=Join-Path $repo 'native\providers\ck_fmha\full_attention_capture_replay.cpp'
$artifacts=@()
$sourceFiles=@($source,(Join-Path $repo 'native\providers\ck_fmha\blackwell_attention.h'))
foreach($directory in @('native\providers\moe_accumulator','native\providers\gdn')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $directory) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
foreach($file in $sourceFiles){$artifacts+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;source_inputs=$artifacts;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();model_loaded=$false;inference_acceptance=$false;model='none; native attention replay build';purpose=$Action}
$spec.memory_layout=$MemoryLayout
$spec.sm121_dpp_reduction=$true
$spec.parallel_probability=($MemoryLayout -eq 24)
$spec.compacted_pv_replay=($MemoryLayout -in @(22,24))
$env:QRT_CK_SM121_NATIVE_PRODUCTS=if($NativeProducts){'1'}else{'0'}
$spec.native_products=[bool]$NativeProducts
$spec.mantissa_wmma=($MemoryLayout -eq 5)
$spec.integer_wmma=($MemoryLayout -eq 5 -or ($MemoryLayout -ge 18 -and $MemoryLayout -le 21))
$spec.native_mma_pv=($MemoryLayout -in @(6,7,13,22,23,24))
$spec.native_mma_qk=($MemoryLayout -eq 7 -or $MemoryLayout -eq 14)
$spec.selective_exact_pv=($MemoryLayout -in @(13,22,23,24))
$spec.tiled_exact_qk=(($MemoryLayout -ge 15 -and $MemoryLayout -le 17) -or $MemoryLayout -in @(22,23,24))
$spec.cell_parallel_integer_qk=($MemoryLayout -eq 18 -or $MemoryLayout -eq 20)
$spec.sparse_integer_core_qk=($MemoryLayout -ge 19 -and $MemoryLayout -le 21)
$spec.prepacked_integer_core=($MemoryLayout -eq 21)
$spec.prepared_value_encoding=($MemoryLayout -ge 17 -and $MemoryLayout -le 21)
$spec.environment_overrides=@{QRT_CK_SM121_NATIVE_PRODUCTS=$env:QRT_CK_SM121_NATIVE_PRODUCTS}
$spec.ck_provider_commit='cf5da6481b13278212d102b2050bd54180b773dc'
$spec.ck_provider_sha256='b6619750cb9bd397c0f8c3f79cdf0ab96d7f929374e16fa4ad8d0b543b39af78'
$env:QRT_CK_FMHA_SM121_FULL_PREFIX=if($UseRcp){'1'}else{'0'}
$env:QRT_CK_FMHA_SM121_EXP2_TABLE='D:\projects\sm121-exp2-negative-f490940d.bin'
if($UseRcp){
 $rcp='D:\projects\sm121-attention-rcp-d2e55754.bin'
 if((Get-FileHash $rcp -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'd2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39'){throw 'Reciprocal table changed'}
 $env:QRT_CK_FMHA_SM121_RCP_TABLE=$rcp
 $spec.reciprocal_table=@{file=$rcp;sha256='d2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39';capture_sha256='0d5c590a4078c9fe6f6c90186d7cfb4c815b8a38225903e914cb868f9a3a1fe0'}
}else{Remove-Item Env:QRT_CK_FMHA_SM121_RCP_TABLE -ErrorAction SilentlyContinue}
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','--offload-arch=gfx1151',$source,'-lbcrypt','-o',$exe)
 $out=Join-Path $repo 'build\attention-build-r1';$timeout=300
}else{
 $manifest=[IO.File]::ReadAllText((Join-Path $build 'build-provenance.json'))|ConvertFrom-Json
 if($manifest.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $manifest.executable.sha256){throw 'Replay executable provenance mismatch'}
 $captureRoot='D:\projects\AIMA-public-fa-out-20260911\build\fla-model-q7169-fa-out-r1'
 $q=Join-Path $captureRoot 'layer3-full-full_attention_q_norm_rope-bf16.bin'
 $k=Join-Path $captureRoot 'layer3-full-full_attention_k_norm_rope-bf16.bin'
 $v=Join-Path $captureRoot 'layer3-full-full_attention_v_projection-bf16.bin'
 $reference='D:\projects\full-attention-context-gb10-08734309.bin'
 $ck='D:\projects\AIMA-public-replicated-carry-20260911\build\ck\qrt_ck_fmha_sm121.dll'
 $inputs=@(
  @{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},@{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'},@{file=$v;sha256='bd95f94c94ea0606c94b6d98548a672e78479bf6df2d7ace08f3797a85907e80'},@{file=$reference;sha256='f3d9b30a1e70f97a5510a0242006e91e0754207bb8e437cdf46d777bfb6fed33'},
  @{file=$ck;sha256='b6619750cb9bd397c0f8c3f79cdf0ab96d7f929374e16fa4ad8d0b543b39af78'}
 )
 foreach($file in $inputs){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Replay input fingerprint mismatch'}}
 $out=Join-Path $repo ('build\attention-'+$Name)
 $table=if($UseTable){'D:\projects\sm121-exp2-negative-f490940d.bin'}else{'-'}
 $baselineFlag=if($Baseline){'1'}else{'0'}
 $spec.executable=$exe
 $spec.arguments=@($q,$k,$v,$reference,$ck,(Join-Path $out 'attention'),'7169',[string]$QueryStart,[string]$QueryCount,[string]$Batch,$table,$baselineFlag,[string]$MemoryLayout)
 $spec.model='D:\models\Qwen3.6-35B-A3B; captured real q7169 layer-3 Q/K/V'
 $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83'
 $spec.input_run_sha256='4a4334d65056371866a10626bec395f9778a2cb6a182ead0560c35ea5cb20146'
 $spec.input_whole_source='28c4f9df501e8e95ac357acc45d30daf48633bf8'
 $spec.input_files=$inputs
 $spec.reference_host='aitopatom-66c4'
 $spec.reference_capture_sha256='087343091048d50a12977548a24a6f2a0fd3346352bceb42fb160c3cf6a6bd37'
 $spec.reference_oracle_sha256='7fa645e8111932279e71ad20b9a1117b5f5f4f26074fdd43c7b2d274a86ac121'
 $spec.reference_is_compute_input=$false
 $timeout=180
}
$specPath=Join-Path $build ($Action+'-'+$Name+'-spec.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Output exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout | Out-Null
$record=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$record|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($file in @('product.stdout.jsonl','product.stderr.log')){if(Test-Path (Join-Path $out $file)){[IO.File]::ReadAllLines((Join-Path $out $file))|Select-Object -Last 15}}
if($record.reason -ne 'completed' -or ($record.exit_code -ne 0 -and -not ($Action -eq 'replay' -and $record.exit_code -eq 2)) -or -not $record.host_checks_pass){throw 'Native action or host check failed'}
if($Action -eq 'build'){
 $manifest=[ordered]@{repo_commit=$sha;source_inputs=$artifacts;host=[Environment]::MachineName;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($manifest|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}

if($Action -eq 'replay'){
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne $(if($Baseline){2}else{1})){throw 'Missing attention numerical reports'}
 $matched=($reports[-1].elements -eq $QueryCount*4096 -and $reports[-1].bf16_mismatches -eq 0 -and $reports[-1].nonfinite -eq 0)
 $expectedF32='71b486111bd9d21a3f3b09e9aa8966321aaa73df9873395bdb6ebf220ee141f4'
 $rawControl=@();foreach($artifactName in @('attention-ck-f32.bin','attention-blackwell-sm121-exp-rcp-f32.bin')){if(-not (Test-Path (Join-Path $out $artifactName))){continue};$actual=(Get-FileHash (Join-Path $out $artifactName) -Algorithm SHA256).Hash.ToLowerInvariant();$rawControl+=@{file=$artifactName;sha256=$actual;matches_qualified_native=($actual -eq $expectedF32)}}
 $manifest=@(Get-ChildItem $out -File -Filter '*.bin'|Sort-Object Name|ForEach-Object {@{file=$_.Name;bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
 [IO.File]::WriteAllText((Join-Path $out 'file-manifest.json'),($manifest|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
 [ordered]@{bf16_reference_match=$matched;native_raw_f32_control=$rawControl;elements=$QueryCount*4096;f32_control_sha256=$expectedF32;reports=$reports}|ConvertTo-Json -Depth 5
}

param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-attention-parallel-probability-20260913';$seed='D:\projects\AIMA-public-attention-compact-pv-20260913'
$sha='df1cd185dc503a6da850153a20c7612ba43a0bc9';$bundle='D:\projects\attention-parallel-probability-df1cd18.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '0651a36afecd2b3fe92a7d285fb2147045c9677fa8f23e19f3ef17f587c3f792'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\parallel-probability-safety';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\parallel_probability_selftest.cpp';$exe=Join-Path $build 'parallel-probability-safety.exe'
$sourceInputs=@();foreach($name in @('tests\native\parallel_probability_selftest.cpp','native\providers\ck_fmha\blackwell_attention.h','native\providers\moe_accumulator\sm121_pv_error_bound.h','tests\native\scaled_l2_reference.h','native\providers\triton_moe\qrt_triton_moe_q8192_provider.cpp','native\providers\triton_moe\routed_parallel_gate.h','native\providers\moe_accumulator\q1_moe_hawkeye_bf16_accumulator.h','native\providers\moe_accumulator\sm121_wave16.h','native\providers\moe_accumulator\sm121_lane_reduce.h','native\providers\moe_accumulator\sm121_prefill_projection.h','native\providers\moe_accumulator\bf16_scaled_l2.h','native\providers\moe_accumulator\sm121_subgroup.h','native\providers\moe_accumulator\sm121_paired_products.h','native\providers\moe_accumulator\sm121_group16_modulo.h','native\providers\moe_accumulator\sm121_shared_gate.h','native\providers\moe_accumulator\bf16_midpoint_selector.h')){$sourceInputs+=@{file=$name;sha256=(Get-FileHash (Join-Path $repo $name) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; Original one-wave versus eight-wave probability generation; synthetic finite scores including K65536; both reduction orders and exact SM121 table';model_loaded=$false;inference_acceptance=$false}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $link=Join-Path $build 'hipblaslt.lib';Copy-Item 'C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a' $link
 $spec.link_inputs=@(@{file=$link;sha256=(Get-FileHash $link -Algorithm SHA256).Hash.ToLowerInvariant()})
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','--offload-arch=gfx1151','-L',$build,$source,'-o',$exe,'-lhipblaslt');$timeout=120
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $table='D:\projects\sm121-exp2-negative-f490940d.bin'
 $tableSha='f490940df2bd80421159a96424c3e922330b7ca120d5ae7b629a973b9183730b'
 if((Get-FileHash $table -Algorithm SHA256).Hash.ToLowerInvariant() -ne $tableSha){throw 'Exp2 table fingerprint mismatch'}
 $spec.exp2_table=@{file=$table;sha256=$tableSha;bytes=(Get-Item $table).Length}
 $spec.executable=$exe;$spec.arguments=@($table);$timeout=90
}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\parallel-probability-safety-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 12|ForEach-Object {$_.Substring(0,[Math]::Min(700,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native safety action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;link_inputs=$spec.link_inputs;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne 216){throw 'Missing probability safety cases'}
 foreach($report in $reports){if($report.kind -ne 'parallel_probability' -or $report.probability_bit_mismatches -ne 0 -or $report.scale_bit_mismatches -ne 0 -or -not $report.redzones_pass -or -not $report.immutable_inputs){throw 'Probability safety failure'}}
}
